type proxyListeners struct {
	mux           *multiplexer.Mux
	ssh           net.Listener
	web           net.Listener
	reverseTunnel net.Listener
	kube          net.Listener
	db            net.Listener
}

// setRegisteredListenerAddress records the address returned by the OS so
// exported file descriptors and restarted processes use the bound endpoint.
func (process *TeleportProcess) setRegisteredListenerAddress(typ listenerType, listener net.Listener) {
	process.Lock()
	defer process.Unlock()

	addr := listener.Addr().String()
	for i := range process.registeredListeners {
		if process.registeredListeners[i].typ == typ {
			process.registeredListeners[i].address = addr
		}
	}
}

func (l *proxyListeners) Close() {
	if l.mux != nil {
		l.mux.Close()
	}
	if l.ssh != nil {
		l.ssh.Close()
	}
	if l.web != nil {
		l.web.Close()
	}
	if l.reverseTunnel != nil {
		l.reverseTunnel.Close()
	}
	if l.kube != nil {
		l.kube.Close()
	}
	if l.db != nil {
		l.db.Close()
	}
}

